/**
 * Starts a new project from a live one. The caller picks the name, slug and
 * key; description, visibility, colour and lead come from the source. The
 * slug is uniquified the same way a created project's slug is. Included
 * issues are the live ones only, renumbered from 1 in source-number order,
 * with progress cleared. Comments are never copied. One `project.cloned`
 * event announces the batch.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const includeIssues = input.includeIssues !== false;
  const toCopy = includeIssues
    ? await issueRepo.listLiveIssuesByNumber(input.orgId, source.id)
    : [];

  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, toCopy.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.slug);

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const status = defaultIssueStatus(org.settings.defaultIssueStatus);
  let issuesCopied = 0;

  for (const issue of toCopy) {
    issuesCopied += 1;
    await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: project.id,
        title: issue.title,
        description: issue.description,
        status,
        priority: issue.priority,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        labelIds: [...issue.labelIds],
      },
      actor.userId,
      issuesCopied,
    );
  }

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return project;
}

