/**
 * Temporary verification for project cloning. Deleted after the run.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { eq } from "drizzle-orm";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { cloneProjectSchema } from "@/schemas/project";
import { getDb, projects } from "@/server/db";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerSearchListeners, search } from "@/server/services/search-service";
import { listActivity } from "@/server/services/activity-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { IssueStatus } from "@/types/issue";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function cloneInput(
  orgId: CloneProjectInput["orgId"],
  projectId: CloneProjectInput["projectId"],
  overrides: Partial<CloneProjectInput> = {},
): CloneProjectInput {
  return {
    orgId,
    projectId,
    name: overrides.name ?? "Release train",
    slug: overrides.slug ?? "release-train",
    key: overrides.key ?? "REL",
    includeIssues: overrides.includeIssues ?? true,
  };
}

describe("cloneProject", () => {
  it("copies a fresh project and live issues, and leaves the source alone", async () => {
    const offActivity = registerActivityListeners();
    const offSearch = registerSearchListeners();
    const offUsage = registerUsageListeners();

    const created: string[] = [];
    const cloned: unknown[] = [];
    const issueCreated: unknown[] = [];
    const offCreated = subscribe("project.created", () => {
      created.push("yes");
    });
    const offCloned = subscribe("project.cloned", (payload) => {
      cloned.push(payload);
    });
    const offIssue = subscribe("issue.created", (payload) => {
      issueCreated.push(payload);
    });

    try {
      const tenant = await createTenant("clonehappy", "growth");
      await orgRepo.updateOrg(tenant.org.id, {
        orgId: tenant.org.id,
        settings: { defaultIssueStatus: "todo" },
      });
      await projectService.updateProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        description: "Checklist body",
        visibility: "private",
        status: "paused",
        leadId: tenant.userIds.admin,
        color: "#112233",
        targetDate: toIsoTimestamp("2026-12-01T00:00:00.000Z"),
      });
      const stamp = toIsoTimestamp("2026-04-01T00:00:00.000Z");
      getDb()
        .update(projects)
        .set({ startsAt: stamp })
        .where(eq(projects.id, tenant.project.id))
        .run();

      const label = await labelRepo.insertLabel({
        orgId: tenant.org.id,
        name: "train",
        color: "#abcdef",
        description: null,
      });

      const low = await issueRepo.insertIssue(
        {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          title: "Second in source order",
          description: "keep me",
          status: "backlog",
          priority: "low",
          assigneeId: null,
          parentId: null,
          estimate: 2,
          dueAt: toIsoTimestamp("2026-08-01T00:00:00.000Z"),
          labelIds: [label.id],
        },
        tenant.userIds.owner,
        10,
      );
      const high = await issueRepo.insertIssue(
        {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          title: "First in source order",
          description: "also keep",
          status: "backlog",
          priority: "urgent",
          assigneeId: tenant.userIds.member,
          parentId: low.id,
          estimate: 5,
          dueAt: null,
          labelIds: [],
        },
        tenant.userIds.owner,
        3,
      );
      await issueRepo.setIssueStatus(tenant.org.id, high.id, "in_progress");
      await issueRepo.setIssueAssignee(
        tenant.org.id,
        high.id,
        tenant.userIds.admin,
      );
      const archived = await issueRepo.insertIssue(
        {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          title: "Archived source issue",
          description: "do not copy",
          status: "done",
          priority: "high",
          assigneeId: tenant.userIds.owner,
          parentId: null,
          estimate: 1,
          dueAt: null,
          labelIds: [label.id],
        },
        tenant.userIds.owner,
        1,
      );
      await issueRepo.archiveIssue(tenant.org.id, archived.id);

      await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: high.id,
        body: "a conversation",
        parentId: null,
        mentionedUserIds: [],
      });
      await attachmentRepo.insertAttachment(
        {
          orgId: tenant.org.id,
          issueId: high.id,
          filename: "notes.txt",
          contentType: "text/plain",
          sizeBytes: 12,
        },
        tenant.userIds.member,
      );

      const sourceBefore = await projectRepo.findProjectById(
        tenant.org.id,
        tenant.project.id,
      );
      const highBefore = await issueRepo.findIssueById(tenant.org.id, high.id);

      await usageRepo.recomputeUsage(tenant.org.id);
      const usageBefore = await usageRepo.getUsage(tenant.org.id);

      const clonedProject = await projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant.org.id, tenant.project.id, {
          name: "Next train",
          slug: "next-train",
          key: "NXT",
        }),
      );

      expect(clonedProject).toMatchObject({
        orgId: tenant.org.id,
        name: "Next train",
        slug: "next-train",
        key: "NXT",
        description: "Checklist body",
        visibility: "private",
        status: "active",
        leadId: tenant.userIds.admin,
        color: "#112233",
        startsAt: null,
        targetDate: null,
        archivedAt: null,
      });
      expect(clonedProject.id).not.toBe(tenant.project.id);

      const sourceAfter = await projectRepo.findProjectById(
        tenant.org.id,
        tenant.project.id,
      );
      expect(sourceAfter).toEqual(sourceBefore);
      const highAfter = await issueRepo.findIssueById(tenant.org.id, high.id);
      expect(highAfter).toEqual(highBefore);

      const copies = await issueRepo.listLiveIssuesByNumber(
        tenant.org.id,
        clonedProject.id,
      );
      expect(copies.map((issue) => issue.number)).toEqual([1, 2]);
      expect(copies.map((issue) => issue.title)).toEqual([
        "First in source order",
        "Second in source order",
      ]);
      expect(copies[0]).toMatchObject({
